import { useId } from "react";
import type { AgentRuntime } from "../api/types.js";

/**
 * 运行时产品图标:用各家真实品牌标识,让用户一眼分辨 Agent 跑在哪个 Agent 系统上。
 *
 * 素材来源(均为各产品公开标识,品牌名称与标识归各自权利人所有):
 * - Claude Code:Anthropic 官方 sunburst 标识,陶土橙 #D97757(取自 SquadSight 的 AgentIcon.tsx)
 * - WorkBuddy:腾讯 WorkBuddy 官方标识,青绿渐变 #0EC8A9 → #01C886(取自 SquadSight 的 AgentIcon.tsx)
 * - Codex:OpenAI 官方标识,蓝紫渐变 #B1A7FF → #7A9DFF → #3941FF(取自 paperclip/ui/public/brands/codex-color.svg)
 * - DeepSeek:官方鲸鱼标识,蓝 #4D6BFE(取自 PilotDeck/ui/public/onboarding/providers/deepseek-color.svg)
 */
export interface RuntimeIconProps {
  runtime: AgentRuntime;
  /** 图标边长,默认 16 */
  size?: number;
}

/** 运行时品牌标识;自身仅作装饰,全名由外层 Tooltip 的 aria-label 给出 */
export function RuntimeIcon({ runtime, size = 16 }: RuntimeIconProps) {
  switch (runtime) {
    case "claude_code":
      return <ClaudeCodeMark size={size} />;
    case "workbuddy":
      return <WorkBuddyMark size={size} />;
    case "codex":
      return <CodexMark size={size} />;
    case "deepseek":
      return <DeepSeekMark size={size} />;
  }
}

